"""Package authored Blender renders with their alpha, without stretching/cropping."""
from pathlib import Path
import json,subprocess,base64,argparse
root=Path(__file__).resolve().parents[1];art=root/'art/arsenal-v4';assets=root/'app/src/superhealth/assets/arsenal'
p=argparse.ArgumentParser();p.add_argument('--partial',action='store_true');args=p.parse_args()
items=json.loads((art/'items.json').read_text());images={}
for c in items:
 src=art/'renders'/f"{c['id']}.png";dest=art/'renders'/f"{c['id']}.webp"
 if not src.exists():
  if args.partial:continue
  raise FileNotFoundError(src)
 subprocess.run(['magick',str(src),'-resize','640x640','-quality','91','-define','webp:alpha-quality=100',str(dest)],check=True)
 images[c['id']]='data:image/webp;base64,'+base64.b64encode(dest.read_bytes()).decode()
(assets/'atelier-images.js').write_text("'use strict';\n// Original Blender renders, lossless alpha. Generated by tools/build-atelier-assets.py.\nconst AtelierImages="+json.dumps(images,separators=(',',':'))+';\n')
(assets/'atelier-data.js').write_text("'use strict';\n// Authored catalogue: 21 complete sets, 84 original constructions.\nconst AtelierData="+json.dumps(items,ensure_ascii=False,separators=(',',':'))+".map((c,i)=>({...c,name:[c.title],set:{id:c.setId,name:c.setName},available:true,edition:4,rarity:c.tier,signature:c.tier===4,number:401+i,variant:i,stat:({weapon:'Bras',chest:'Pectoraux',guard:'Dos',legs:'Jambes'})[c.slot],roll:WeaponStudy.tiers[c.tier].range[0]+((i*37+13)%(WeaponStudy.tiers[c.tier].range[1]-WeaponStudy.tiers[c.tier].range[0]+1)),colors:equipmentSchools[c.school].colors,color:equipmentSchools[c.school].colors[0]}));\n")
print(f'{len(images)} original 3D illustrations packaged; '+str((assets/'atelier-images.js').stat().st_size)+' bytes')
